async function(vars) {
	var dataSource = await model.getDatasource({
		endpoint: "B2B/OfferLine",
		odataAppend: "?$filter=OfferId eq " + vars.offerId + "&$expand=InvoiceReference,CreditReference"
	});
	var lineGrid  = new GridWidget(vars.element, dataSource);
	lineGrid.editable = false;
	lineGrid.sortable = false;
	lineGrid.filterable = false;
	lineGrid.pageable = false;
	lineGrid.scrollable = false;
	lineGrid.groupable = false;
	lineGrid.columns = [
		{ field: "LineNumber", type: "number", title: "[resource_shortdisplayname[LineNumber]]", width: 70,  },
		{ template: "#=(InvoiceReferenceId) ? '[resource_shortdisplayname[SalesInvoice]]' : '[resource_shortdisplayname[creditnote]]'#", title: "[resource_displayname[type]]", width: 50 },
		{ field: "TransactionValue", type: "number", title: "[resource_shortdisplayname[facevalue]]", description: "[resource_description[facevalue]]", format: "{0:" + type.moneyFormat + "}", width: 90, attributes:{style:"text-align:right;"}},
		{ field: "TaxAmount", type: "number", title: "[resource_shortdisplayname[taxamount]]", format: "{0:" + type.moneyFormat + "}", width: 90, attributes:{style:"text-align:right;"}},
		{ field: "FundableValue", type: "number", title: "[resource_shortdisplayname[fundablevalue]]", format: "{0:" + type.moneyFormat + "}", width: 90, attributes:{style:"text-align:right;"}},
		{ field: "LinePrice", type: "number", title: "[resource_shortdisplayname[offervalue]]", description: "[resource_description[OfferValue]]", format: "{0:" + type.moneyFormat + "}", width: 90, attributes:{style:"text-align:right;"}},
		{ field: "Rate", type: "number", format: "{0:" + type.moneyFormat + "}", title: "[resource_shortdisplayname[rate]]", description: "[resource_description[rate]]", attributes:{style:"text-align:right;"}},
		{ field: "Cost", type: "number", format: "{0:" + type.moneyFormat + "}", title: "[resource_displayname[cost]]", description: "resource_description[cost]", attributes:{style:"text-align:right;"}},
		{ field: "CurrencyId", type: "string", title: "[resource_shortdisplayname[CurrencyId]]", width: 70 }
	];
    lineGrid.commands.push({
        name: "view",
        icon: "k-i-view",
        template: `<a href='/Transactions/#=(InvoiceReferenceId) ? "Invoice?Id=" + InvoiceReference.InvoiceId : "Credit?Id=" + CreditReference.CreditId#'><span class='k-icon k-i-share'></span>[resource_displayname[view]]</a>`
    })
	vars.LineGrid = lineGrid;
	return lineGrid;
}
